			function doSave(param){
				
				// 저장 서브미션 호출
				util.Submit.send(app, param + "", function(pbSuccess){
					if(pbSuccess){
						
						app.lookup('dmSearch').clear();
						app.lookup("dmDeleteIdx").clear();
						app.lookup("cmnsinglefileuploadweb1").removeAllFiles();
						app.lookup("cmnsinglefileupload2").removeAllFiles();
						app.lookup("cmnimageviewer1").removeAllViewImage();
						
						doList("save");
						
					}
				});
			}

